250	    private Sheet record(Sheet sheet, String user, String key, BigDecimal value, LocalDate from, String text,
251	            boolean moves) {
252	        String sheetId = sheet.getId();
253	        RollupService.Snapshot before = moves ? rollup.snapshot(sheetId) : null;
254	        sheet.record(key, from != null ? from : sheet.getToday(), value);
255	        Sheet saved = sheetStore.saveAndFlush(sheet);
256	        audit.recordOnCommit(changed(sheetId, user, key, text) + (from != null ? " from=" + from : ""));
257	        if (moves) {
